const input = params.input ?? params.text;
const pattern = params.pattern;
if (typeof input !== 'string') throw new Error('params.input (string) required');
if (!pattern) throw new Error('params.pattern required');
const flags = params.flags || 'g';
const action = (params.action || 'match').toLowerCase();
const re = new RegExp(pattern, flags);
if (action === 'test') return { matched: re.test(input) };
if (action === 'replace') {
  const replacement = params.replacement ?? '';
  return { result: input.replace(re, replacement) };
}
// action: match
const matches = [];
let m;
const gre = new RegExp(pattern, flags.includes('g') ? flags : flags + 'g');
let guard = 0;
while ((m = gre.exec(input)) !== null) {
  matches.push({ match: m[0], groups: m.slice(1), index: m.index });
  if (m.index === gre.lastIndex) gre.lastIndex++;
  if (++guard > 1000) break;
}
return { pattern, flags, count: matches.length, matches };
